const runData = $input.first().json.data.resultData.runData;
const nodosWorkflow = $input.first().json.workflowData.nodes;

let totalCompletionTokens = 0;
let totalPromptTokens = 0;
let totalTokens = 0;

let proveedor = "Desconocido";
let nombreNodoEjecutado = "";
let ejecuciones = [];

// Verificar proveedor del modelo
if (runData['Ollama Chat Model']) {
    ejecuciones = runData['Ollama Chat Model'];
    proveedor = "ollama";
    nombreNodoEjecutado = "Ollama Chat Model";
} else if (runData['Google Gemini Chat Model']) {
    ejecuciones = runData['Google Gemini Chat Model'];
    proveedor = "google";
    nombreNodoEjecutado = "Google Gemini Chat Model";
} else if (runData['OpenAI Chat Model']) {
    ejecuciones = runData['OpenAI Chat Model'];
    proveedor = "openai";
    nombreNodoEjecutado = "OpenAI Chat Model";
} else {
    return { error: "No se encontró Ollama, Gemini ni OpenAI en esta ejecución" };
}

// Extraer nombre del modelo usado
let modeloEspecifico = "Desconocido";

if (ejecuciones.length > 0) {
    const opcionesRuntime = ejecuciones[0].inputOverride?.ai_languageModel?.[0]?.[0]?.json?.options;
    if (opcionesRuntime && opcionesRuntime.model) {
        modeloEspecifico = opcionesRuntime.model;
    }
}

// Para modelos que no guardan el nombre en las ejecuciones
if (modeloEspecifico === "Desconocido") {
    const nodoConfigurado = nodosWorkflow.find(nodo => nodo.name === nombreNodoEjecutado);
    if (nodoConfigurado && nodoConfigurado.parameters) {
        modeloEspecifico = nodoConfigurado.parameters.model || nodoConfigurado.parameters.modelName || "Desconocido";
    }
}

// Contamos los tokens de todas las ejecuciones
for (const ejecucion of ejecuciones) {
    try {
        const jsonDatos = ejecucion.data?.ai_languageModel?.[0]?.[0]?.json;
        if (!jsonDatos) continue; 

        let tokensInfo;

        if (proveedor === "ollama") {
            tokensInfo = jsonDatos.tokenUsageEstimate;
        } else if (proveedor === "google" || proveedor === "openai") {
            // n8n suele normalizar los tokens en 'tokenUsage'
            tokensInfo = jsonDatos.tokenUsage;

            // Fallback por si devuelve el formato crudo nativo de la API de OpenAI
            if (!tokensInfo && jsonDatos.usage) {
                tokensInfo = {
                    completionTokens: jsonDatos.usage.completion_tokens,
                    promptTokens: jsonDatos.usage.prompt_tokens,
                    totalTokens: jsonDatos.usage.total_tokens
                };
            }
        }

        if (tokensInfo) {
            totalCompletionTokens += (tokensInfo.completionTokens || 0);
            totalPromptTokens += (tokensInfo.promptTokens || 0);
            totalTokens += (tokensInfo.totalTokens || 0);
        }
    } catch (error) {
        continue;
    }
}

return {
    modelProvider: proveedor,
    modelName: modeloEspecifico,
    completionTokens: totalCompletionTokens,
    promptTokens: totalPromptTokens,
    totalTokens: totalTokens
};
